"""Regenerates the AUTO-GENERATED section of specific RAG documents from
real current data -- real database rows for a bank's rate document, a
live fetch of rbi.org.in for RBI's policy-rates document.

Closes the gap documented since the original HDFC investigation
(PROJECT_STATUS.md Sections 44-45, and re-confirmed 2026-11-05 after 51
days of the daily pipeline only ever refreshing automation.duckdb, never
the plain-English documents chat actually reads from): a real rate change
in the database was never reflected in chat, because nothing regenerated
the document or rebuilt the search index from it.

Scope of this version (PROJECT_STATUS.md Section 62, Step 1 of a 5-step
plan): the RBI policy-rates document and HDFC's FD document only. This is
a deliberate pilot, not the full rollout -- see that section for what
isn't built yet (other banks, the daily workflow wiring, a drift check).

Marker convention, by design, not incidental: a document's
"<!--AUTO:START-->" / "<!--AUTO:END-->" lines bound the ONLY region this
script ever rewrites. Everything outside those markers -- explanatory
prose, caveats, methodology notes -- is hand-written and untouched. If a
document has no markers, this script does nothing to it -- it never
introduces markers into a document nobody asked to automate, and never
guesses at a different document structure.

The "do not hand-edit, regenerated by this script" explanation that used
to live INSIDE the marker line itself (as visible document text) moved
here instead (2026-11-05): that explanation was ~185 characters of a
single document's chunk-0 text, consumed before any real content, which
pushed real figures (e.g. a bank's 1-year FD rate) out of General Chat's
500-character preview window -- a real, measured regression, not a
theoretical one. The markers are now a short, content-free HTML-comment
style tag; build_index.py strips both marker lines from the text it
indexes/embeds entirely (see its own comment), so they cost 0 characters
in any retrieval path, not just a smaller number of them. If you are
reading this because you opened a document and wondered what the
"<!--AUTO:START-->" tag means: the lines between it and the matching
"<!--AUTO:END-->" are regenerated by this script from real current
data (automation.duckdb for a bank's rate document, a live fetch of
rbi.org.in for RBI's) -- do not hand-edit those figures, they will be
overwritten the next time this script runs; edit the hand-written
sections outside the markers instead.

Run standalone:
    python automation/sync_rag_docs.py
"""

from __future__ import annotations

import re
import sys
import urllib.request
from datetime import datetime, timezone
from pathlib import Path

AUTOMATION_DIR = Path(__file__).resolve().parent
PROJECT_ROOT = AUTOMATION_DIR.parents[0]
sys.path.insert(0, str(AUTOMATION_DIR))

from db import get_connection  # noqa: E402
from tenure_utils import tenure_covers  # noqa: E402

_START_LINE = "<!--AUTO:START-->"
_END_LINE = "<!--AUTO:END-->"
_USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"

RBI_HOME_URL = "https://www.rbi.org.in/"
RBI_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "rbi" / "rbi_current_policy_rates.txt"
HDFC_FD_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "hdfc" / "hdfc_fd_rates.txt"
SBI_FD_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "sbi" / "sbi_fd_rates.txt"
BOB_FD_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "bob" / "bob_fd_rates.txt"
CANARA_FD_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "canara" / "canara_fd_rates.txt"
PNB_FD_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "pnb" / "pnb_fd_rates.txt"
UNION_BANK_FD_DOC_PATH = PROJECT_ROOT / "data" / "raw" / "union_bank" / "union_bank_fd_rates.txt"


def _replace_marked_block(text: str, new_body: str) -> str | None:
    """Swaps the content strictly BETWEEN the START/END marker lines for
    new_body, keeping the marker lines themselves and everything outside
    them byte-for-byte untouched. Returns None if the document has no
    markers at all (nothing to do, not an error)."""
    lines = text.splitlines(keepends=True)
    start_i = next((i for i, l in enumerate(lines) if l.strip() == _START_LINE), None)
    end_i = next((i for i, l in enumerate(lines) if l.strip() == _END_LINE), None)
    if start_i is None or end_i is None or end_i <= start_i:
        return None
    return "".join(lines[: start_i + 1] + [new_body] + lines[end_i:])


def _update_date_header(text: str, new_date: str) -> str:
    return re.sub(r"(?m)^DATE:\s*\S+\s*$", f"DATE: {new_date}", text, count=1)


# ───────────────────────────────── RBI policy rates ───────────────────

# Confirmed directly against the real page 2026-11-05: rbi.org.in's
# homepage renders its "Policy Rates"/"Reserve Ratios" figures as plain
# <th>label</th>...<td>: value</td> pairs inside two accordion tables --
# no JS rendering needed, a plain fetch sees them. This regex doesn't
# care which accordion a row is in; it just needs the row label to be one
# of the ones listed in `_WANTED` below.
_ROW_RE = re.compile(r"<th[^>]*>\s*([^<]+?)\s*</th>\s*<td[^>]*>\s*:?\s*([\d.]+%?)\s*</td>", re.S)

# Real label text on the page (confirmed 2026-11-05) -> this document's
# own established names, and whether that line gets a " p.a." suffix.
_WANTED = {
    "Policy Repo Rate": ("Repo Rate", True),
    "Fixed Reverse Repo Rate": ("Reverse Repo Rate", True),
    "Marginal Standing Facility Rate": ("Marginal Standing Facility (MSF) Rate", True),
    "Bank Rate": ("Bank Rate", True),
    "CRR": ("Cash Reserve Ratio (CRR)", False),
    "SLR": ("Statutory Liquidity Ratio (SLR)", False),
}


def fetch_rbi_current_rates() -> list[tuple[str, str]] | None:
    """Real current values scraped directly from rbi.org.in's own
    homepage. Returns None -- never a guess, never the old value padded
    back in -- if the fetch fails or the page no longer has one of the
    expected labels, since that means the page structure changed and a
    confirmed-correct regex match can no longer be trusted."""
    try:
        req = urllib.request.Request(RBI_HOME_URL, headers={"User-Agent": _USER_AGENT})
        with urllib.request.urlopen(req, timeout=15) as resp:
            html = resp.read().decode("utf-8", errors="replace")
    except Exception as e:
        print(f"[sync_rag_docs] RBI homepage fetch failed: {type(e).__name__}: {e}", flush=True)
        return None

    found = {label.strip(): value.strip() for label, value in _ROW_RE.findall(html)}
    missing = [real for real in _WANTED if real not in found]
    if missing:
        print(f"[sync_rag_docs] RBI homepage is missing expected label(s) {missing} "
              f"-- page structure may have changed, not regenerating", flush=True)
        return None

    return [
        (doc_label, found[real_label] + (" p.a." if wants_pa else ""))
        for real_label, (doc_label, wants_pa) in _WANTED.items()
    ]


def regenerate_rbi_doc() -> bool:
    """Returns True if the document's content actually changed on disk."""
    rates = fetch_rbi_current_rates()
    if rates is None:
        return False

    text = RBI_DOC_PATH.read_text(encoding="utf-8")
    now = datetime.now(timezone.utc)
    today_label = f"{now.day} {now.strftime('%B %Y')}"

    lines = [f"As of {today_label} (live-fetched from rbi.org.in), RBI's key policy rates are:\n", "\n"]
    for label, value in rates:
        lines.append(f"{label}: {value}\n")
    new_body = "".join(lines)

    new_text = _replace_marked_block(text, new_body)
    if new_text is None:
        print("[sync_rag_docs] rbi_current_policy_rates.txt has no AUTO-GENERATED markers -- skipping")
        return False
    new_text = _update_date_header(new_text, now.strftime("%Y-%m-%d"))

    if new_text == text:
        return False
    RBI_DOC_PATH.write_text(new_text, encoding="utf-8")
    return True


# ───────────────────────────────── bank FD documents ──────────────────

def _fd_rows_for_bank(bank_id: str) -> list[tuple]:
    """Real current fd_rates rows for one bank, in the real fetch's own
    row order (DuckDB preserves insertion order; extract_structured.py
    inserts in the source page's own tenure order) -- not re-sorted, so
    the document's tenure listing stays in the same order a human reading
    the bank's own page would see, same as before this script existed."""
    con = get_connection()
    rows = con.execute(
        "SELECT tenure_label, interest_rate_general, interest_rate_senior, "
        "effective_date, fetched_at FROM fd_rates "
        "WHERE bank_id = ? AND product_type = 'fixed_deposit' AND deposit_variant = 'retail'",
        [bank_id],
    ).fetchall()
    con.close()
    return rows


# The ~1/2/3/5-year points are the tenures people actually ask about
# most ("what's your 1-year rate") -- pulling them to the front of the
# generic template's table means they land near the START of the chunk,
# which matters concretely for General Chat's 500-char preview (PNB's
# 1-year line was otherwise pushed out by everything before it in the
# table). This is a pure reordering, not a relabeling -- every row keeps
# its own real tenure_label text exactly as the database has it, so
# there's no risk of mischaracterizing a band as "the N-year rate" when
# it's actually a sub-variant; it only decides what's shown first.
#
# BUG FOUND 2026-11-06 (the verification-sheet investigation): the
# original version matched labels with a simple text-prefix regex
# ("starts with '3 Years'"), not real day-count math. For HDFC
# specifically, the actual 3-year and 5-year POINTS (days 1095/1825) fall
# inside compound bands worded like "2 Years 11 Months 1 day <= 3 Year" --
# the prefix regex never matches that, so it promoted the WRONG
# neighboring band (one that starts the day after, not the one that
# actually covers the point) to the front of the table. Confirmed via the
# verification sheet: Compare Rates (which already uses tenure_covers()
# for this exact question) showed 6.55%/7.05% for HDFC's 3-year rate and
# 6.60%/7.20% for its 5-year rate; the old regex-based reordering
# surfaced 6.6%/7.2% and 6.6%/7.1% instead -- silently wrong, and
# inconsistent with what Compare Rates says for the same bank's "3 year"/
# "5 year" question. Fixed by using tenure_covers() -- the SAME day-count
# logic compare_for_tenure() already uses -- instead of a parallel,
# looser implementation. Same tie-break rule too: when more than one
# row's range includes the target day (a real ambiguity in some banks'
# own interval wording, not a bug), the higher general rate wins, exactly
# as compare_for_tenure() already does.
_COMMON_TENURE_DAYS = {1: 365, 2: 730, 3: 1095, 5: 1825}


def _reorder_common_tenures_first(rows: list[tuple]) -> list[tuple]:
    remaining = list(rows)
    front = []
    for days in _COMMON_TENURE_DAYS.values():
        matches = [i for i, r in enumerate(remaining) if tenure_covers(r[0], days)]
        if not matches:
            continue
        best_i = max(matches, key=lambda i: remaining[i][1])  # r[1] = interest_rate_general
        front.append(remaining.pop(best_i))
    return front + remaining


def regenerate_bank_fd_doc(
    bank_id: str, doc_path: Path, bank_display_name: str, manual_snapshot_note: str | None = None,
) -> bool:
    """Returns True if the document's content actually changed on disk.
    Regenerates BOTH the summary paragraph and the tenure table from the
    same query result, in the same run -- so the two can never disagree
    with each other the way a hand-maintained summary sentence could
    silently drift from a hand-maintained table.

    `manual_snapshot_note`, if given, is appended as its own sentence --
    for a bank whose fd_rates rows come from a hand-maintained CSV
    (`load_manual_snapshots.py`), not a live fetch (Union Bank, added
    2026-11-07 after its FD page became a persistent WAF block -- see
    config/banks.json's union_bank note), so the document itself says so
    rather than reading identically to a live-fetched bank's."""
    rows = _fd_rows_for_bank(bank_id)
    if not rows:
        print(f"[sync_rag_docs] no fd_rates rows found for {bank_id!r} -- skipping")
        return False

    text = doc_path.read_text(encoding="utf-8")

    generals = [g for _, g, _, _, _ in rows if g is not None]
    seniors = [s for _, _, s, _, _ in rows if s is not None]
    min_rate, max_rate = min(generals), max(generals)
    premiums = sorted({round(s - g, 2) for _, g, s, _, _ in rows if g is not None and s is not None})
    if not seniors:
        # Confirmed 2026-11-07 (Union Bank's manual snapshot): no
        # senior-citizen rate was found on the bank's own page for this
        # table at all -- NOT the same case as "every tenure shares one
        # premium" or "premiums vary by tenure" below. Never invents a
        # premium (not even by copying one from elsewhere, e.g. an
        # older, now-superseded hand-written document for the same
        # bank) -- the per-row table lines already say "not published"
        # for each one; this sentence just states the same fact once,
        # up front, instead of leaving it to be inferred 18 times over.
        premium_sentence = "No senior-citizen rate was published alongside this table."
    elif len(premiums) == 1:
        premium_sentence = (
            f"with senior citizens earning a flat additional {premiums[0]:g}% over the general rate."
        )
    else:
        # Shortened 2026-11-06: the original wording ("...on most tenures
        # (one or more bands carry a wider premium -- the table below
        # always shows each band's own real senior rate, never assume a
        # flat X%).") pushed the table's first row past 500 characters
        # for both HDFC and PNB -- measured directly, not assumed --
        # keeping the generic template from ever reaching real tenure
        # figures within General Chat's preview window even after common
        # tenures were reordered to the front. Same meaning, ~90 fewer
        # characters: still names the flat rate, still warns the table
        # has the real per-band figure.
        flat = min(premiums)  # the common case; any wider premium is named per-row in the table itself
        premium_sentence = (
            f"with senior citizens earning {flat:g}% more on most tenures "
            f"(see the table for each band's exact rate)."
        )

    # fd_rates.fetched_at is stored as VARCHAR (confirmed directly, not
    # assumed -- unlike fetch_log.fetched_at, which is a real TIMESTAMP
    # column), so this is real string comparison/slicing, not datetime math.
    latest_fetch_str = max(fetched_at for *_, fetched_at in rows)
    effective_dates = {eff for *_, eff, _ in rows if eff}
    effective_label = (
        sorted(effective_dates)[-1] if len(effective_dates) == 1
        else latest_fetch_str[:10]
    )
    effective_human = _human_date(datetime.strptime(effective_label, "%Y-%m-%d")) \
        if re.match(r"^\d{4}-\d{2}-\d{2}$", effective_label) else effective_label

    # "with senior citizens..." continues the previous sentence after a
    # comma; the no-senior-data case is its own standalone sentence, so
    # the line before it needs a period instead.
    range_line_end = "." if not seniors else ","
    lines = [
        f"{bank_display_name}'s current fixed deposit (FD) interest rate for the general\n",
        f"public ranges from {min_rate:g}% to {max_rate:g}% per annum across its tenures{range_line_end}\n",
        f"{premium_sentence}\n",
        "\n",
        f"Effective {effective_human}, rates by tenure (general public / senior citizen):\n",
    ]
    for tenure_label, g, s, _, _ in _reorder_common_tenures_first(rows):
        g_s = f"{g:g}%" if g is not None else "not published"
        s_s = f"{s:g}%" if s is not None else "not published"
        lines.append(f"- {tenure_label}: {g_s} / {s_s}\n")
    if manual_snapshot_note:
        # Appended AFTER the table, not before it -- General Chat's
        # 500-char preview budget is tight enough already (see the
        # premium_sentence shortening above, same investigation); this
        # note is important provenance but not as time-critical as the
        # 1-year figure actually being inside that window.
        lines.append("\n")
        lines.append(f"{manual_snapshot_note}\n")
    new_body = "".join(lines)

    new_text = _replace_marked_block(text, new_body)
    if new_text is None:
        print(f"[sync_rag_docs] {doc_path.name} has no AUTO-GENERATED markers -- skipping")
        return False
    new_text = _update_date_header(new_text, latest_fetch_str[:10])

    if new_text == text:
        return False
    doc_path.write_text(new_text, encoding="utf-8")
    return True


# Windows' strftime has no %-d; this works on both Windows and POSIX.
def _human_date(dt: datetime) -> str:
    return f"{dt.day} {dt.strftime('%B %Y')}"


# ───────────────── batch 1: SBI, BOB, Canara, PNB (2026-11-05) ─────────
#
# Unlike HDFC's pilot (which normalizes every bank into one generic
# template), batch 1 keeps each bank's own existing hand-written wording,
# spacing, and decimal-formatting convention completely untouched --
# per-bank requirement: "replace only the figures and the fetched date
# inside [the markers], and keep the hand-written framing text". This
# means surgical in-place substitution of just the numeric tokens next to
# each already-known label, not rebuilding the paragraph from scratch.
#
# _sub_number_pair/_sub_number raise (never silently skip) if a label or
# its expected 'N%' isn't found where expected -- a drifted label is
# exactly the Punjab & Sind / IndusInd class of bug this project has hit
# before; guessing a new mapping is worse than failing loudly.

def _sub_number_pair(text: str, label_literal: str, first: float, second: float,
                      decimals: int = 2, search_window: int = 200) -> str:
    """Finds label_literal, then the next 'N% ... N%' pair after it, and
    replaces just the two numbers -- the separator between them (spacing,
    '|', '/', etc.) and everything else is copied through unchanged."""
    idx = text.find(label_literal)
    if idx == -1:
        raise ValueError(f"label {label_literal!r} not found in document")
    m = re.compile(r"([\d.]+)%(.*?)([\d.]+)%", re.DOTALL).search(text, idx)
    if m is None or m.start() > idx + search_window:
        raise ValueError(f"no 'N% ... N%' pair found within {search_window} chars after label {label_literal!r}")
    new_segment = f"{first:.{decimals}f}%{m.group(2)}{second:.{decimals}f}%"
    return text[: m.start()] + new_segment + text[m.end() :]


def _sub_number(text: str, label_literal: str, value: float,
                 decimals: int = 2, search_window: int = 120) -> str:
    """Same as _sub_number_pair but for a single 'N%' after the label."""
    idx = text.find(label_literal)
    if idx == -1:
        raise ValueError(f"label {label_literal!r} not found in document")
    m = re.compile(r"[\d.]+%").search(text, idx)
    if m is None or m.start() > idx + search_window:
        raise ValueError(f"no 'N%' found within {search_window} chars after label {label_literal!r}")
    return text[: m.start()] + f"{value:.{decimals}f}%" + text[m.end() :]


def _rows_by_label(bank_id: str) -> dict[str, tuple]:
    """Real current retail fd_rates rows for one bank, keyed by the
    database's own tenure_label text -- for banks whose document doesn't
    list rows in a 1:1, position-stable order with the database (unlike
    HDFC's single full table), so matching by label text is the safer,
    explicit choice; a label that no longer exists in today's data raises
    a clear KeyError at the call site rather than silently misattributing
    a neighboring row's figures."""
    return {label: (g, s, eff, fetched) for label, g, s, eff, fetched in _fd_rows_for_bank(bank_id)}


def _effective_human_for(values: list[tuple]) -> str:
    """Same rule HDFC's/SBI's regeneration already uses: prefer the
    bank's own effective_date when every row agrees on one (the normal
    case -- it's the bank's own stated effective date, not when WE
    happened to fetch), falling back to our own fetch date only if rows
    disagree. Using fetched_at here instead would be wrong whenever we
    re-verify a bank's rates without the bank itself having changed
    anything -- exactly the BOB/Canara/PNB case this fixes."""
    effective_dates = {eff for _g, _s, eff, _fetched in values if eff}
    latest_fetch_str = max(fetched for _g, _s, _eff, fetched in values)
    effective_label = sorted(effective_dates)[-1] if len(effective_dates) == 1 else latest_fetch_str[:10]
    return _human_date(datetime.strptime(effective_label, "%Y-%m-%d"))


def regenerate_sbi_fd_doc() -> bool:
    """SBI's retail table happens to match the database 1:1, in the same
    order, so this just confirms that (raises if it ever stops matching)
    and substitutes each of the 8 tenor lines' two numbers plus the
    opening paragraph's 'last updated'/'effective' dates. The Non-Callable
    and Amrit Vrishti/Patrons sections stay outside the markers --
    _fd_rows_for_bank only covers deposit_variant='retail', so those
    sections have no fresh data source here and are left hand-written."""
    rows = _fd_rows_for_bank("sbi")
    expected_order = [
        "7 days to 45 days", "46 days to 179 days", "180 days to 210 days",
        "211 days to less than 1 year", "1 Year to less than 2 years",
        "2 years to less than 3 years", "3 years to less than 5 years",
        "5 years and up to 10 years",
    ]
    actual_order = [label for label, *_ in rows]
    if actual_order != expected_order:
        print(f"[sync_rag_docs] sbi: retail row order/labels changed from what this "
              f"function expects ({actual_order} vs {expected_order}) -- skipping rather "
              f"than risk misattributing a row")
        return False

    text = SBI_FD_DOC_PATH.read_text(encoding="utf-8")
    body = _replace_marked_block(text, "")  # presence check only
    if body is None:
        print("[sync_rag_docs] sbi_fd_rates.txt has no AUTO-GENERATED markers -- skipping")
        return False

    lines = [
        "Tenor: 7 days to 45 days       ->",
        "Tenor: 46 days to 179 days     ->",
        "Tenor: 180 days to 210 days    ->",
        "Tenor: 211 days to <1 year     ->",
        "Tenor: 1 year to <2 years      ->",
        "Tenor: 2 years to <3 years     ->",
        "Tenor: 3 years to <5 years     ->",
        "Tenor: 5 years to 10 years     ->",
    ]
    new_text = text
    for line_label, (_, g, s, _eff, _fetched) in zip(lines, rows):
        new_text = _sub_number_pair(new_text, line_label, g, s)

    latest_fetch_str = max(fetched_at for *_, fetched_at in rows)
    effective_dates = {eff for *_, eff, _ in rows if eff}
    effective_label = sorted(effective_dates)[-1] if len(effective_dates) == 1 else latest_fetch_str[:10]
    effective_human = _human_date(datetime.strptime(effective_label, "%Y-%m-%d"))
    last_updated_human = _human_date(datetime.strptime(latest_fetch_str[:10], "%Y-%m-%d"))

    new_text = re.sub(r"last updated \d{1,2} [A-Za-z]+ \d{4}", f"last updated {last_updated_human}", new_text, count=1)
    new_text = re.sub(r"effective \d{1,2} [A-Za-z]+ \d{4}", f"effective {effective_human}", new_text, count=1)
    new_text = _update_date_header(new_text, latest_fetch_str[:10])

    if new_text == text:
        return False
    SBI_FD_DOC_PATH.write_text(new_text, encoding="utf-8")
    return True


def regenerate_bob_fd_doc() -> bool:
    """BOB's document already omits 2 of the bank's 16 published retail
    rows (a pre-existing, pre-automation content gap, not introduced
    here) -- this only refreshes the 14 lines the document already has,
    by label, and never adds the 2 missing rows (out of scope: this task
    is about keeping existing figures fresh, not expanding coverage)."""
    by_label = _rows_by_label("bob")
    text = BOB_FD_DOC_PATH.read_text(encoding="utf-8")
    if _replace_marked_block(text, "") is None:
        print("[sync_rag_docs] bob_fd_rates.txt has no AUTO-GENERATED markers -- skipping")
        return False

    line_to_label = {
        "- 7-14 days:": "7 days to 14 days",
        "- 15-45 days:": "15 days to 45 days",
        "- 46-90 days:": "46 days to 90 days",
        "- 91-180 days:": "91 days to 180 days",
        "- 181-210 days:": "181 days to 210 days",
        "- 211-270 days:": "211 days to 270 days",
        "- 271 days to <1 year:": "271 days & above and less than 1 year",
        "- 1 year:": "1 year",
        "- >1 year to 400 days:": "Above 1 year to 400 days",
        "- >2-3 years:": "Above 2 Years and upto 3 Years",
        "- >3-5 years:": "Above 3 Years and upto 5 Years",
        "- >5-10 years:": "Above 5 Years and upto 10 Years",
        "- bob Square Drive (444 days):": "bob Square Drive Deposit Scheme (444 Days)",
        "- bob Golden Goal (555 days):": "bob Golden Goal deposit Scheme (555 Days)",
    }
    new_text = text
    for line_label, db_label in line_to_label.items():
        if db_label not in by_label:
            print(f"[sync_rag_docs] bob: label {db_label!r} not found in today's retail rows -- skipping this run")
            return False
        g, s, _eff, _fetched = by_label[db_label]
        new_text = _sub_number_pair(new_text, line_label, g, s)

    latest_fetch_str = max(fetched_at for _, _, _, fetched_at in by_label.values())
    new_text = re.sub(
        r"Effective \d{1,2} [A-Za-z]+ \d{4}",
        f"Effective {_effective_human_for(by_label.values())}",
        new_text, count=1,
    )
    new_text = _update_date_header(new_text, latest_fetch_str[:10])

    if new_text == text:
        return False
    BOB_FD_DOC_PATH.write_text(new_text, encoding="utf-8")
    return True


def regenerate_canara_fd_doc() -> bool:
    """Canara's document is a headline range + 3 selected tenors + one
    special-tenor paragraph, not a full table -- regenerates the range
    (min/max general, min/max senior across all retail rows), the 3
    selected tenors (the 'around 1 year' line maps to the bank's current
    '1 Year & above...' band, since a standalone '1 year' band no longer
    exists), and the 555-day senior figure the special-tenor paragraph
    separately restates."""
    by_label = _rows_by_label("canara")
    text = CANARA_FD_DOC_PATH.read_text(encoding="utf-8")
    if _replace_marked_block(text, "") is None:
        print("[sync_rag_docs] canara_fd_rates.txt has no AUTO-GENERATED markers -- skipping")
        return False

    generals = [g for g, _s, _eff, _fetched in by_label.values()]
    seniors = [s for _g, s, _eff, _fetched in by_label.values()]
    min_g, max_g = min(generals), max(generals)
    min_s, max_s = min(seniors), max(seniors)

    one_year_label = next((l for l in by_label if l.startswith("1 Year")), None)
    rate_555 = by_label.get("555 Days")
    if one_year_label is None or rate_555 is None:
        print("[sync_rag_docs] canara: expected labels ('1 Year...' / '555 Days') not found -- skipping")
        return False

    new_text = text
    new_text = _sub_number_pair(new_text, "General Public range:", min_g, max_g)
    new_text = _sub_number_pair(new_text, "citizens:", min_s, max_s)
    new_text = _sub_number(new_text, "- 7-45 days:", by_label["7 Days to 45 Days"][0])
    new_text = _sub_number(new_text, "- 46-90 days:", by_label["46 Days to 90 Days"][0])
    new_text = _sub_number(new_text, "- 1 year:", by_label[one_year_label][0])
    new_text = _sub_number(new_text, "555-day scheme offers", rate_555[1])  # senior rate

    latest_fetch_str = max(fetched_at for *_, fetched_at in by_label.values())
    new_text = re.sub(
        r"Effective \d{1,2} [A-Za-z]+ \d{4}",
        f"Effective {_effective_human_for(by_label.values())}",
        new_text, count=1,
    )
    new_text = _update_date_header(new_text, latest_fetch_str[:10])

    if new_text == text:
        return False
    CANARA_FD_DOC_PATH.write_text(new_text, encoding="utf-8")
    return True


# PNB's document used to keep its own distinctive per-line wording (same
# as SBI/BOB/Canara), but the bank has since restructured two regions of
# its tenure table (91-154/155/156-179 collapsed into one '91 to 179
# Days' band; 390-666/667 days' boundaries shifted to a different
# 443/679/680/681 split, and the special high-rate day moved from 666 to
# 680) -- a changed ROW COUNT, not just changed numbers, which a
# label-by-label substitution can't handle without guessing a mapping
# (9 of the old 23 lines had no reliable current equivalent; an earlier
# version of this function froze those 9, flagged but stale).
#
# 2026-11-05: switched to the HDFC-style approach instead -- the generic
# regenerate_bank_fd_doc() rebuilds the summary paragraph and the full
# tenure table from scratch, straight from today's real retail rows in
# their own order, so a changed row count is handled automatically, not
# a special case. This means PNB's table now reads in HDFC's generic
# template wording rather than its old distinctive phrasing -- a
# deliberate tradeoff for this bank specifically (not applied to
# SBI/BOB/Canara), since "preserve the exact old wording" and "stop
# showing 9 stale lines under a fresh date" are not both achievable once
# the bank's own row count has changed. The markers were narrowed to
# wrap only the summary+table (matching HDFC's own marker scope) -- the
# "Senior Citizen Premium" and "444 Days Special Scheme" paragraphs
# moved outside, back to hand-written, same category as the Uttam/Pranam
# scheme paragraphs already there (the 444-day paragraph's 2 figures can
# drift from the table over time as a disclosed consequence; it was last
# synced with the table at the time of this change).
def regenerate_pnb_fd_doc() -> bool:
    return regenerate_bank_fd_doc("pnb", PNB_FD_DOC_PATH, "Punjab National Bank")


# Union Bank's FD page became a persistent WAF block (confirmed
# 2026-11-07 -- see config/banks.json's union_bank note and
# PROJECT_STATUS.md §64/§65); its fd_rates rows now come from a hand-
# maintained CSV (data/manual/union_bank_fd.csv, loaded by
# load_manual_snapshots.py) instead of a live fetch. Uses the same
# generic HDFC-style template as PNB -- no 1:1 row-order/position
# assumption needed, and the generic template already handles a bank
# with no senior-citizen data at all (see regenerate_bank_fd_doc()'s
# `not seniors` branch, added for this bank specifically).
def regenerate_union_bank_fd_doc() -> bool:
    return regenerate_bank_fd_doc(
        "union_bank", UNION_BANK_FD_DOC_PATH, "Union Bank of India",
        manual_snapshot_note=(
            "This table is a manually-maintained snapshot (data/manual/union_bank_fd.csv), "
            "not a live daily fetch -- see README Known Limitations."
        ),
    )


def run() -> dict[str, bool]:
    """Returns {name: changed?} for every document this pilot covers."""
    results = {}
    results["rbi_current_policy_rates"] = regenerate_rbi_doc()
    results["hdfc_fd_rates"] = regenerate_bank_fd_doc("hdfc", HDFC_FD_DOC_PATH, "HDFC Bank")
    results["sbi_fd_rates"] = regenerate_sbi_fd_doc()
    results["bob_fd_rates"] = regenerate_bob_fd_doc()
    results["canara_fd_rates"] = regenerate_canara_fd_doc()
    results["pnb_fd_rates"] = regenerate_pnb_fd_doc()
    results["union_bank_fd_rates"] = regenerate_union_bank_fd_doc()
    return results


if __name__ == "__main__":
    results = run()
    for name, changed in results.items():
        print(f"{name}: {'UPDATED' if changed else 'no change / skipped'}")
